from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
TOOLS = ROOT / "tools" / "mirror_sync"

REQUEST_WRITER = TOOLS / "gate_chain_publisher.py"
RESULT_WRITER = TOOLS / "universal_job_result_publisher.py"
HEALTH_WRITER = TOOLS / "runtime_health_publisher.py"

CANONICAL_WRITERS = {
    "worker/requests": REQUEST_WRITER,
    "worker/results": RESULT_WRITER,
    "worker/health": HEALTH_WRITER,
}

SCAN_SUFFIXES = {".py", ".sh"}


def _source(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def _runtime_sources():
    for path in TOOLS.rglob("*"):
        if not path.is_file():
            continue
        if path.suffix not in SCAN_SUFFIXES:
            continue
        yield path


def _looks_like_branch_writer(text: str, branch: str) -> bool:
    markers = (
        f"refs/heads/{branch}",
        f'"{branch}"',
        f"'{branch}'",
    )

    if not any(marker in text for marker in markers):
        return False

    write_markers = (
        "git push",
        '"push"',
        "'push'",
        "authorized_push(",
        "scoped_push_env(",
        "runtime_git(",
        "runtime_git_command(",
    )

    return any(marker in text for marker in write_markers)


def test_worker_channels_have_one_canonical_writer_each():
    offenders = {}

    for branch, canonical in CANONICAL_WRITERS.items():
        found = []

        for path in _runtime_sources():
            text = _source(path)

            if _looks_like_branch_writer(text, branch):
                found.append(path.resolve())

        canonical_resolved = canonical.resolve()

        unexpected = sorted(
            str(path.relative_to(ROOT))
            for path in found
            if path != canonical_resolved
        )

        if unexpected:
            offenders[branch] = unexpected

    assert offenders == {}, (
        "Non-canonical Worker branch writers detected: "
        + repr(offenders)
    )


def test_canonical_request_writer_is_gate_chain_publisher():
    text = _source(REQUEST_WRITER)

    assert "worker/requests" in text
    assert "authorized_push(" in text
    assert "worktree-create" in text
    assert "worker_queue_publication" in text


def test_canonical_result_writer_is_result_publisher():
    text = _source(RESULT_WRITER)

    assert "worker/results" in text
    assert "publish_one" in text


def test_canonical_health_writer_is_health_publisher():
    text = _source(HEALTH_WRITER)

    assert "worker/health" in text
    assert "production_touched" in text


def test_request_result_health_channels_remain_separate():
    request = _source(REQUEST_WRITER)
    result = _source(RESULT_WRITER)
    health = _source(HEALTH_WRITER)

    assert "worker/results" not in request
    assert "worker/health" not in request

    assert "worker/requests" not in result
    assert "worker/health" not in result

    assert "worker/requests" not in health
    assert "worker/results" not in health
